<?php $e=static fn(mixed $v):string=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); ?>
<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Aufbewahrung – MeldeVerkehr</title>
<style>body{font-family:system-ui,sans-serif;background:#f5f7fa;color:#172033;margin:0}main{max-width:950px;margin:28px auto;padding:20px}.card{background:#fff;border:1px solid #dfe5ec;border-radius:15px;padding:20px;margin-bottom:14px}.warn{padding:12px;border:1px solid #d6b36b;background:#fffaf0;border-radius:8px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:12px}.kpi{font-size:1.6rem;font-weight:800}table{width:100%;border-collapse:collapse}td,th{padding:8px;border-bottom:1px solid #e5e9ee;text-align:left}.muted{color:#66758a}</style></head><body><main><p><a href="/dashboard">← Dashboard</a></p><h1>Aufbewahrung & Löschvorschau</h1>
<div class="warn">Automatische Löschung geschlossener Fälle ist standardmäßig deaktiviert. Diese Seite zeigt Planung und Datenbestände; konkrete produktive Fristen müssen separat fachlich/rechtlich konfiguriert werden.</div>
<section class="card"><h2>Datenbestand</h2><div class="grid"><?php foreach($overview['counts'] as $key=>$value):?><div><div class="muted"><?= $e($key) ?></div><div class="kpi"><?= $e($value) ?></div></div><?php endforeach;?></div></section>
<section class="card"><h2>Account-Löschvorschau</h2><h3>Sofort technisch löschbar</h3><?php foreach($deletionPreview['immediately_deletable'] as $k=>$v):?><p><?= $e($k) ?>: <strong><?= $e($v) ?></strong></p><?php endforeach;?><h3>Vor Löschung zu prüfen</h3><?php foreach($deletionPreview['review_required'] as $k=>$v):?><p><?= $e($k) ?>: <strong><?= $e($v) ?></strong></p><?php endforeach;?><p class="muted"><?= $e($deletionPreview['note']) ?></p></section>
<section class="card"><h2>Retention-Planung</h2><table><tr><th>Typ</th><th>Policy</th><th>Frühestens</th><th>Status</th><th>Hinweis</th></tr><?php foreach($overview['schedules'] as $s):?><tr><td><?= $e($s['data_type']) ?></td><td><?= $e($s['policy_key']) ?></td><td><?= $e($s['eligible_at']??'–') ?></td><td><?= $e($s['status']) ?></td><td><?= $e($s['reason']??'') ?></td></tr><?php endforeach;?></table></section>
</main><script src="/assets/app.js" defer></script></body></html>